#if UNITY_EDITOR
using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;

namespace ProjectSpark.AutoLevelGenerator.Editor
{
    /// <summary>
    /// Read-only source/art preflight for Level 105. Does not create electrical contacts,
    /// modify component progress, certify routes, or award mission objectives.
    /// </summary>
    public static class SparkAutoL105SourceValidator
    {
        private const string ReportPath =
            "Assets/ProjectSpark/AutoGeneratedLevels/Level105/L105_Source_Import_Audit.txt";
        private const string MainBoard = "101_L105_PCB_ENX13_270x190mm.obj";
        private const string EndpointBoard = "110_L105_ECX4_RemovableCard.obj";
        private const string Showcase = "129_L105_AssembledMainboardReference.obj";

        [MenuItem("Tools/Project Spark/Automatic Level Generator/105/3. Validate source models and PBR")]
        public static void ValidateSource()
        {
            var report = new StringBuilder(4096);
            report.AppendLine("PROJECT SPARK | LEVEL 105 ENX-13 + ECX-4 | SOURCE IMPORT PREFLIGHT");
            report.AppendLine("This is NOT a Unity Play Mode or electrical certification test.");
            string root = FindSourceRoot();
            if (string.IsNullOrEmpty(root))
            {
                Debug.LogError("[L105 Audit] Missing or ambiguous Level 105 Data/ModelManifest.csv. " +
                    "Keep exactly one Level105_ENX13 source kit under Assets.");
                return;
            }

            int failures = 0;
            report.AppendLine("Source: " + root);
            AssertCount(report, ref failures, "FBX models (including assembled reference)",
                CountFiles(root + "/Models_FBX", "*.fbx"), 129);
            AssertCount(report, ref failures, "GLB models (including assembled reference)",
                CountFiles(root + "/Models_GLB", "*.glb"), 129);
            AssertCount(report, ref failures, "OBJ mesh fallbacks", 
                CountFiles(root + "/Models_OBJ_Fallback", "*.obj"), 129);
            AssertCount(report, ref failures, "Source PNG maps", 
                CountFiles(root + "/Textures", "*.png"), 49);
            AssertCount(report, ref failures, "URP packed PNG maps", 
                CountFiles(root + "/Textures/Unity_Packed", "*.png"), 32);
            AssertCount(report, ref failures, "PBR albedo families", 
                CountFiles(root + "/Textures", "*_Albedo.png"), 16);
            AssertCount(report, ref failures, "Model-manifest rows",
                CountCsvRows(root + "/Data/ModelManifest.csv"), 128);
            AssertCount(report, ref failures, "BOM component rows",
                CountCsvRows(root + "/Data/ComponentBOM.csv"), 100);
            AssertCount(report, ref failures, "Component-placement rows",
                CountCsvRows(root + "/Data/ComponentPlacements.csv"), 100);
            AssertCount(report, ref failures, "Unverified route records",
                CountCsvRows(root + "/Data/CopperRoutes_132_REQUIRES_SCHEMATIC.csv"), 132);
            AssertCount(report, ref failures, "Unverified via records",
                CountCsvRows(root + "/Data/ViaTasks_38_REQUIRES_SCHEMATIC.csv"), 38);
            CheckMesh(report, ref failures, root, MainBoard);
            CheckMesh(report, ref failures, root, EndpointBoard);
            CheckMesh(report, ref failures, root, Showcase);
            report.AppendLine();
            report.AppendLine("Required engineering gates (currently not source-approved):");
            report.AppendLine("- Board footprint targets: main ENX-13 0.270 x 0.190 m; ECX-4 0.080 x 0.035 m");
            report.AppendLine("- All 132 routes: missing approved pad/net assignments");
            report.AppendLine("- All 38 vias: missing approved net/layer spans");
            report.AppendLine("- W133: logical U12/U13 labels, missing physical monitor/supervisor pins");
            report.AppendLine("- Electrical solver, PCIe link training, tools and LevelGamePlayManager: unbound");
            report.AppendLine("- No UI or visual interaction can award objectives from this preflight");
            report.AppendLine();
            report.AppendLine("OFFLINE SOURCE/UNITY IMPORT PREFLIGHT: " +
                (failures == 0 ? "PASS (assets only; NOT PLAYABLE)" : "FAIL (" + failures + " asset checks)"));

            string outputAbsolute = ToAbsolute(ReportPath);
            string directory = Path.GetDirectoryName(outputAbsolute);
            if (!string.IsNullOrEmpty(directory)) Directory.CreateDirectory(directory);
            File.WriteAllText(outputAbsolute, report.ToString());
            AssetDatabase.Refresh();
            if (failures == 0) Debug.Log("[L105 Audit] " + report);
            else Debug.LogError("[L105 Audit] " + report);
        }

        private static string FindSourceRoot()
        {
            string found = null;
            string[] guids = AssetDatabase.FindAssets("ModelManifest");
            for (int index = 0; index < guids.Length; index++)
            {
                string assetPath = AssetDatabase.GUIDToAssetPath(guids[index]).Replace('\\', '/');
                if (!assetPath.EndsWith("/Data/ModelManifest.csv", StringComparison.OrdinalIgnoreCase))
                    continue;
                if (assetPath.IndexOf("Level105", StringComparison.OrdinalIgnoreCase) < 0 &&
                    assetPath.IndexOf("ENX13", StringComparison.OrdinalIgnoreCase) < 0 &&
                    assetPath.IndexOf("ExpansionNexus", StringComparison.OrdinalIgnoreCase) < 0)
                    continue;
                string sourceRoot = Path.GetDirectoryName(Path.GetDirectoryName(assetPath));
                if (string.IsNullOrEmpty(sourceRoot)) continue;
                sourceRoot = sourceRoot.Replace('\\', '/');
                if (found != null && !string.Equals(found, sourceRoot, StringComparison.OrdinalIgnoreCase))
                    return null;
                found = sourceRoot;
            }
            return found;
        }

        private static int CountFiles(string folder, string pattern)
        {
            string absolute = ToAbsolute(folder);
            if (!Directory.Exists(absolute)) return 0;
            return Directory.GetFiles(absolute, pattern, SearchOption.TopDirectoryOnly).Length;
        }

        private static int CountCsvRows(string csvPath)
        {
            string absolute = ToAbsolute(csvPath);
            if (!File.Exists(absolute)) return 0;
            int rows = 0;
            bool header = true;
            using (var reader = new StreamReader(absolute))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    if (string.IsNullOrWhiteSpace(line)) continue;
                    if (header) { header = false; continue; }
                    rows++;
                }
            }
            return rows;
        }

        private static void CheckMesh(StringBuilder report, ref int failures, string root, string filename)
        {
            string assetPath = root + "/Models_OBJ_Fallback/" + filename;
            GameObject asset = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
            bool renderable = false;
            if (asset != null)
            {
                MeshFilter[] filters = asset.GetComponentsInChildren<MeshFilter>(true);
                for (int index = 0; index < filters.Length; index++)
                {
                    if (filters[index].sharedMesh != null && filters[index].sharedMesh.vertexCount > 0)
                    {
                        renderable = true;
                        break;
                    }
                }
                if (!renderable)
                {
                    SkinnedMeshRenderer[] skinned = asset.GetComponentsInChildren<SkinnedMeshRenderer>(true);
                    for (int index = 0; index < skinned.Length; index++)
                    {
                        if (skinned[index].sharedMesh != null && skinned[index].sharedMesh.vertexCount > 0)
                        {
                            renderable = true;
                            break;
                        }
                    }
                }
            }
            report.AppendLine((renderable ? "PASS: " : "FAIL: ") + "Renderable OBJ: " + filename);
            if (!renderable) failures++;
        }

        private static void AssertCount(StringBuilder report, ref int failures,
            string label, int actual, int expected)
        {
            bool correct = actual == expected;
            report.AppendLine((correct ? "PASS: " : "FAIL: ") + label +
                " = " + actual + " (expected " + expected + ")");
            if (!correct) failures++;
        }

        private static string ToAbsolute(string assetPath)
        {
            string project = Directory.GetParent(Application.dataPath).FullName;
            return Path.Combine(project, assetPath.Replace('/', Path.DirectorySeparatorChar));
        }
    }
}
#endif
